import{_ as t,o as a,c as l,ag as o}from"./chunks/framework.B7PviQjB.js";const r="/docs/images/docs-editor/tables-grid-picker.png",n="/docs/images/docs-editor/tables-cell-background.png",m=JSON.parse('{"title":"Insert and edit tables","description":"Insert a table in a doc, add and delete rows and columns, merge cells, color cell backgrounds, and resize columns.","frontmatter":{"title":"Insert and edit tables","description":"Insert a table in a doc, add and delete rows and columns, merge cells, color cell backgrounds, and resize columns.","type":"how-to"},"headers":[],"relativePath":"docs-editor/tables.md","filePath":"docs-editor/tables.md"}'),s={name:"docs-editor/tables.md"};function i(c,e,d,h,b,g){return a(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="insert-and-edit-tables" tabindex="-1">Insert and edit tables <a class="header-anchor" href="#insert-and-edit-tables" aria-label="Permalink to &quot;Insert and edit tables&quot;">​</a></h1><p>Insert a table to lay out rows and columns, then change its structure and colors from the right-click menu.</p><h2 id="insert-a-table" tabindex="-1">Insert a table <a class="header-anchor" href="#insert-a-table" aria-label="Permalink to &quot;Insert a table&quot;">​</a></h2><ol><li>Put the cursor where the table should go.</li><li>Click <strong>Insert table</strong> (grid icon) in the toolbar.</li><li>Move the pointer over the grid to choose the size, up to 10 by 10, and click.</li></ol><p>The table appears at the cursor, and the cursor moves into its first cell. To size the grid with the keyboard, use the arrow keys and press <code>Enter</code>.</p><p><img src="'+r+'" alt="Insert table grid picker with a 4 by 3 area highlighted"></p><h2 id="move-between-cells" tabindex="-1">Move between cells <a class="header-anchor" href="#move-between-cells" aria-label="Permalink to &quot;Move between cells&quot;">​</a></h2><ul><li>Press <code>Tab</code> to go to the next cell and <code>Shift+Tab</code> to go back.</li><li>Press <code>Tab</code> in the last cell to add a new row.</li><li>Click any cell to put the cursor there.</li></ul><h2 id="insert-or-delete-rows-and-columns" tabindex="-1">Insert or delete rows and columns <a class="header-anchor" href="#insert-or-delete-rows-and-columns" aria-label="Permalink to &quot;Insert or delete rows and columns&quot;">​</a></h2><ol><li>Right-click a cell.</li><li>Under <strong>Row</strong>, select <strong>Insert above</strong>, <strong>Insert below</strong>, or <strong>Delete row</strong>.</li><li>Under <strong>Column</strong>, select <strong>Insert left</strong>, <strong>Insert right</strong>, or <strong>Delete column</strong>.</li></ol><h2 id="merge-and-unmerge-cells" tabindex="-1">Merge and unmerge cells <a class="header-anchor" href="#merge-and-unmerge-cells" aria-label="Permalink to &quot;Merge and unmerge cells&quot;">​</a></h2><ol><li>Drag across the cells to select a rectangle of them.</li><li>Right-click the selection and select <strong>Merge cells</strong>.</li></ol><p>To split them again, right-click the merged cell and select <strong>Unmerge cells</strong>. Only merged cells can be split.</p><h2 id="color-a-cell-background" tabindex="-1">Color a cell background <a class="header-anchor" href="#color-a-cell-background" aria-label="Permalink to &quot;Color a cell background&quot;">​</a></h2><ol><li>Click a cell, or drag to select several.</li><li>Right-click and select <strong>Cell background</strong>.</li><li>Click a swatch. To remove the color, select <strong>Reset</strong>.</li></ol><p><img src="'+n+'" alt="Table right-click menu with the Cell background swatches open"></p><h2 id="resize-columns-and-rows" tabindex="-1">Resize columns and rows <a class="header-anchor" href="#resize-columns-and-rows" aria-label="Permalink to &quot;Resize columns and rows&quot;">​</a></h2><ol><li>Point at a border between two columns or two rows. The pointer changes to a resize arrow.</li><li>Drag the border.</li></ol><h2 id="put-a-table-inside-a-cell" tabindex="-1">Put a table inside a cell <a class="header-anchor" href="#put-a-table-inside-a-cell" aria-label="Permalink to &quot;Put a table inside a cell&quot;">​</a></h2><ol><li>Click inside a cell.</li><li>Click <strong>Insert table</strong> and choose a size.</li></ol><p>The new table sits inside that cell and works like any other table.</p><h2 id="delete-a-table" tabindex="-1">Delete a table <a class="header-anchor" href="#delete-a-table" aria-label="Permalink to &quot;Delete a table&quot;">​</a></h2><ol><li>Right-click any cell in the table.</li><li>Select <strong>Delete table</strong>.</li></ol><p>To undo, press <code>⌘+Z</code> / <code>Ctrl+Z</code>.</p><h2 id="comment-on-text-in-a-table" tabindex="-1">Comment on text in a table <a class="header-anchor" href="#comment-on-text-in-a-table" aria-label="Permalink to &quot;Comment on text in a table&quot;">​</a></h2><p>Select text in a cell, right-click, and select <strong>Insert comment</strong>. See <a href="/docs/collaborate/comments.html">Comments</a>.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>Tap ⋮ (<strong>More formatting options</strong>) at the right end of the toolbar and select <strong>Table (3×3)</strong> under <strong>Insert</strong>. A phone always inserts a 3 by 3 table; add rows with <code>Tab</code> in the last cell if you have a keyboard, or on a computer from the right-click menu.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>A table taller than the rest of the page continues on the next page. The header row isn&#39;t repeated there.</li><li>You can&#39;t insert a table in a header or footer.</li><li>You can&#39;t insert a page break inside a table.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/docs-editor/paste-from-other-apps.html">Paste from other apps</a> to paste a spreadsheet range into a table.</li><li><a href="/docs/docs-editor/page-layout.html">Page layout</a> to give a wide table more room with landscape pages.</li><li><a href="/docs/docs-editor/keyboard-shortcuts.html">Keyboard shortcuts</a> for moving around in a table.</li></ul>',32)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
